/**
 * GET /api/portal/client/services/:id/cpanel-sso
 *
 * Returns `{ url }`: a one-time control-panel sign-in address, generated by the C# backend.
 *
 * `MyServicesController` answers with the same object as its staff-side sibling, which is the
 * shape declared here; the page destructures `url` from it.
 *
 * @module server/api/portal/client/services/[id]/cpanel-sso.get
 */

/** What the backend answers a control-panel sign-in request with. */
interface CpanelSsoResult {
  /** The one-time sign-in address. */
  url: string
}

export default defineEventHandler(async (event) => {
  const id = requireRouteParam(event, 'id')

  return await internalApiCall<CpanelSsoResult>(event, `/me/services/${id}/cpanel-sso`)
})
